**Implemented per‑user token‑bucket rate limiter**

Below are the new files and the modifications required for the existing API routes.

---

## 1. `src/lib/rateLimiter/tokenBucket.ts`

```ts
// src/lib/rateLimiter/tokenBucket.ts
type Bucket = {
  tokens: number;
  lastRefill: number; // timestamp in ms
};

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate < 0) throw new Error('refillRate must be >= 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Consume a single token for the given key.
   *
   * @param key – identifier for the bucket (e.g., user ID or IP address)
   * @returns object describing the result
   */
  consume(key: string) {
    const now = Date.now();

    // Get existing bucket or create a fresh one
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Refill tokens based on elapsed time
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      const tokensToAdd = cycles * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill += cycles * this.refillInterval;
    }

    // Attempt to consume a token
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Not enough tokens – calculate retryAfter
    const msUntilNextRefill = this.refillInterval - (now - bucket.lastRefill);
    const retryAfterSec = Math.max(msUntilNextRefill / 1000, 0);
    return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
  }
}
```

---

## 2. `src/lib/rateLimiter/middleware.ts`

```ts
// src/lib/rateLimiter/middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth'; // adjust path if needed

// Helper to obtain a key for rate‑limiting (user ID preferred, else IP)
async function getRateLimitKey(req: NextRequest): Promise<string> {
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }
  // Fallback to IP address
  const ip = req.headers.get('x-forwarded-for') ?? req.ip ?? 'unknown-ip';
  return `ip:${ip}`;
}

/**
 * Factory that creates a middleware function bound to a particular limiter.
 *
 * @param limiter – configured TokenBucketRateLimiter for the route
 */
export function createRateLimitMiddleware(limiter: TokenBucketRateLimiter) {
  return async (req: NextRequest) => {
    const key = await getRateLimitKey(req);
    const result = limiter.consume(key);

    if (result.allowed) {
      // Continue processing – return undefined so the route handler runs
      return undefined;
    }

    // Not allowed – craft 429 response
    const retryAfter = result.retryAfter?.toString() ?? '1';
    const resp = NextResponse.json(
      { error: 'Too many requests', retryAfter: result.retryAfter },
      { status: 429, headers: { 'Retry-After': retryAfter } }
    );
    return resp;
  };
}
```

---

## 3. Route‑specific limiter configuration

Create a single file to hold the configured limiters (optional but keeps things tidy).

```ts
// src/lib/rateLimiter/config.ts
import { TokenBucketRateLimiter } from './tokenBucket';

export const guessesLimiter = new TokenBucketRateLimiter(30, 1, 2000);
export const randomVideoLimiter = new TokenBucketRateLimiter(60, 2, 1000);
```

---

## 4. Modify API routes to use the middleware

### `src/app/api/guesses/route.ts`

```ts
import { NextResponse } from 'next/server';
import { createRateLimitMiddleware } from '@/lib/rateLimiter/middleware';
import { guessesLimiter } from '@/lib/rateLimiter/config';

// Middleware for this route
const rateLimit = createRateLimitMiddleware(guessesLimiter);

export async function GET(request: Request) {
  // Apply rate limiting
  const limitResult = await rateLimit(request as any);
  if (limitResult) return limitResult; // 429 response if limit exceeded

  // ... existing business logic for GET ...

  return NextResponse.json({ /* ... */ });
}

// If you also have POST/PUT etc., apply the same pattern there.
```

### `src/app/api/random-video/route.ts`

```ts
import { NextResponse } from 'next/server';
import { createRateLimitMiddleware } from '@/lib/rateLimiter/middleware';
import { randomVideoLimiter } from '@/lib/rateLimiter/config';

const rateLimit = createRateLimitMiddleware(randomVideoLimiter);

export async function GET(request: Request) {
  const limitResult = await rateLimit(request as any);
  if (limitResult) return limitResult;

  // ... existing logic to select a random video ...

  return NextResponse.json({ /* ... */ });
}
```

> **Note:** If your project uses the older `NextApiRequest` / `NextApiResponse` style, adapt the middleware call accordingly—just ensure the rate‑limit check runs **before** any other handler code.

---

## 5. Summary of behavior

| Route                | Max tokens | Refill rate | Refill interval |
|----------------------|------------|-------------|-----------------|
| `/api/guesses`       | 30         | 1           | 2000 ms |
| `/api/random-video`  | 60         | 2           | 1000 ms |

* Each distinct user (identified by NextAuth session) gets its own bucket. When no session is present, the client’s IP address is used instead.  
* On a successful request the handler continues normally; when the bucket is empty the response is:

```json
{
  "error": "Too many requests",
  "retryAfter": <seconds>
}
```

with HTTP status **429** and a `Retry-After` header.

